            _ = try writer.writeInt(u32, @as(u32, @truncate(path_slice.len)), .little);
            _ = try writer.writeAll(path_slice);
},
}
},
.s3 => |s3| {
_ = try writer.writeInt(u8, 1, .little);
            var path_slice = s3.pathlike.slice();
            _ = &path_slice;
            _ = try writer.writeInt(u32, @as(u32, @truncate(path_slice.len)), .little);
            _ = try writer.writeAll(path_slice);
},
.bytes => |bytes| {
var slice = bytes.slice();
            _ = &slice;
            _ = try writer.writeInt(u32, @truncate(slice.len), .little);
            _ = try writer.writeAll(slice);
            _ = try writer.writeInt(u32, @truncate(bytes.stored_name.slice().len), .little);
            _ = try writer.writeAll(bytes.stored_name.slice());
},
}
    }

pub fn fromArrayList(list: ArrayListUnmanaged(u8), allocator: Allocator) !*Store {
            return Store.init(list.items, allocator);
    }
    pub const File = StoreFile;
    pub const S3 = StoreS3;
    pub const Bytes = StoreBytes;
    pub const Map = HashMap(u64, *WebCore.Blob.Store, IdentityContext(u64), 80);
    pub const Data = union(enum) {
            bytes: StoreBytes,
            file: StoreFile,
            s3: StoreS3,
        };
    pub const SerializeTag = enum(u8) {
            file = 0,
            bytes = 1,
            empty = 2,
        };
};

